use ingetrazo_render::qt_gray::{PathContour,Segment};
fn point(v:&serde_json::Value)->[f64;2]{[v[0].as_f64().unwrap(),v[1].as_f64().unwrap()]}
fn main(){let args=std::env::args().collect::<Vec<_>>();let value:serde_json::Value=serde_json::from_slice(&std::fs::read(&args[1]).unwrap()).unwrap();let paths=value.as_array().unwrap().iter().map(|p|PathContour{start:point(&p["start"]),segments:p["segments"].as_array().unwrap().iter().map(|s|if s["line"].is_array(){Segment::Line(point(&s["line"]))}else{Segment::Cubic{control1:point(&s["cubic"][0]),control2:point(&s["cubic"][1]),to:point(&s["cubic"][2])}}).collect()}).collect::<Vec<_>>();let spans=ingetrazo_render::qt_gray::rasterize_paths(&paths,1_000_000,1_000_000).unwrap();let rows=spans.iter().map(|s|[s.x as i64,s.y as i64,s.len as i64,s.coverage as i64]).collect::<Vec<_>>();std::fs::write(&args[2],serde_json::to_vec(&rows).unwrap()).unwrap();}
